<template><div class="atelier"><aside class="atelier-sidebar"><router-link to="/orders" class="atelier-logo">SUXU<small>素序 · 商家工作室</small></router-link><span class="workspace-label">MERCHANT ATELIER</span><nav><router-link v-for="item in navigation" :key="item.path" :to="item.path"><i :class="item.icon"></i>{{ item.name }}<i class="nav-arrow el-icon-arrow-right"></i></router-link></nav><div class="sidebar-footer"><div class="identity"><span>S</span><div>{{ username }}<small>精品店主理人</small></div></div><el-button type="text" @click="signOut">退出登录 <i class="el-icon-top-right"></i></el-button></div></aside><div class="atelier-body"><header class="atelier-top"><span>工作空间 <i>/</i> {{ $route.meta.title }}</span><div><span class="role-badge">MERCHANT</span><el-button type="text" class="mobile-signout" @click="signOut">退出登录</el-button><span class="top-avatar">S</span></div></header><main class="atelier-main"><router-view/></main><footer class="atelier-footer">SUXU MERCHANT ATELIER <span>好物有序，日常有光。</span></footer></div></div></template>
<script>
import {logout} from '@/api/auth'
export default {data:()=>({navigation:[{path:'/orders',name:'预约工作台',icon:'el-icon-s-order'},{path:'/products',name:'商品与库存',icon:'el-icon-goods'},{path:'/overview',name:'营业概览',icon:'el-icon-data-analysis'},{path:'/settings',name:'店铺设置',icon:'el-icon-setting'}]}),computed:{username(){return this.$store.state.UBD.user&&this.$store.state.UBD.user.username||'主理人'}},methods:{async signOut(){try{await logout();this.$store.commit('UBD/clearAuthSession');this.$router.replace('/login')}catch(e){this.$message.error(e.message)}}}}
</script>
